"""Bail: independently authored article cases, financial consequences and guarantees."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
rows={}
def add(n,s,p,a,c,v,q,t,d):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP])
add(321,'Sem requisitos de preventiva, juiz concede liberdade provisória, com cautelares se necessárias.', ['Art. 319 e critérios do 282 delimitam restrições.', 'Incisos antigos I e II revogados.'], 'Incapacidade de pagar fiança não cria por si motivo cautelar para prender.', 'Não há risco concreto: juiz concede liberdade e avalia necessidade de cautelar.', 'Prisão não se mantém só porque acusado é pobre.', ['Ausência de requisitos impõe liberdade provisória? Sim.', 'Cautelares são sempre todas obrigatórias? Não.'], 'Liberdade provisória','Liberdade durante processo sob condições legais.')
add(322,'Polícia concede fiança somente quando pena máxima não supera quatro anos; demais casos cabem ao juiz, em 48 horas.', ['Exatamente quatro integra limite policial.', 'Verificar vedação de fiança mesmo dentro da faixa.', 'Competência pelo máximo cominado, não por pena imaginada.'], 'Não confundir máximo até quatro com requisito de preventiva superior a quatro.', 'Delito afiançável com máximo de quatro admite arbitramento policial.', 'Máximo de cinco exige requerimento judicial, não arbitramento pela polícia.', ['Máximo exatamente quatro está no limite? Sim.', 'Juiz decide nos demais casos em 48 horas? Sim.'], 'Competência para fiança','Arbitramento conforme pena máxima e vedações.')
add(323,'Fiança não cabe nos crimes constitucionalmente inafiançáveis enumerados.', ['Racismo.', 'Tortura, tráfico ilícito, terrorismo e hediondos.', 'Grupos armados contra ordem constitucional e Estado Democrático.', 'Incisos antigos IV e V revogados.'], 'Inafiançabilidade não é sinônimo universal de prisão preventiva automática nem elimina exame de liberdade sem fiança.', 'Crime hediondo não admite fiança; juiz examina necessidade cautelar e liberdade juridicamente cabível.', 'Crime não incluído na lista ainda pode ter vedação por outra regra.', ['Inafiançável significa automaticamente preventiva? Não.', 'Hediondo admite fiança pelo simples pagamento? Não.'], 'Inafiançabilidade','Vedação da garantia pecuniária, distinta de necessidade de prender.')
add(324,'Também há vedação por quebra no mesmo processo, obrigações descumpridas sem causa, prisão civil/militar ou motivos de preventiva.', ['Quebra anterior na mesma causa ou infração injustificada dos arts. 327/328.', 'Civil/militar têm regimes próprios.', 'Motivos de preventiva excluem fiança como substituição suficiente.'], 'Não generalizar quebra em processo diverso como hipótese textual idêntica; nem restaurar inciso III revogado.', 'Acusado quebra obrigação injustificadamente no mesmo feito e enfrenta vedação.', 'Ausência com justa causa exige análise, sem vedação mecânica.', ['O inciso I fala do mesmo processo? Sim.', 'Justa causa é irrelevante ao descumprimento? Não.'], 'Vedação adicional','Impedimento ligado à situação processual.')
add(325,'Fiança parte de faixas em salários mínimos e pode ser ajustada pela situação econômica nos limites legais.', ['Máximo até quatro: um a cem salários mínimos.', 'Máximo superior a quatro: dez a duzentos.', 'Dispensa pelo art. 350; redução até dois terços; aumento até mil vezes.'], 'Reduzir em dois terços deixa um terço do valor; não confundir reduzir até dois terços com fixar necessariamente dois terços.', 'Valor-base de três salários é reduzido em dois terços e resulta em um.', 'Situação econômica pode justificar dispensa judicial em vez de prisão por pobreza.', ['Faixa até quatro é de um a cem? Sim.', 'Aumento máximo previsto é mil vezes? Sim.'], 'Ajuste econômico','Calibragem da garantia conforme condição financeira.')
add(326,'Arbitramento considera natureza da infração, condições pessoais e econômicas, vida pregressa, periculosidade e custas prováveis.', ['Fundamentar escolha dentro do regime aplicável.', 'Capacidade econômica importa à adequação.'], 'Fiança não deve ser pena antecipada nem valor aleatório.', 'Autoridade justifica valor considerando renda e elementos do caso.', 'Não copiar valor alto sem analisar condições econômicas concretas.', ['Condição econômica é relevante? Sim.', 'Valor pode ser arbitrário? Não.'], 'Arbitramento individualizado','Definição motivada do valor da garantia.')
add(327,'Afiançado comparece quando intimado aos atos do inquérito, instrução e julgamento, integrando regras de justa causa.', ['Termo estabelece obrigação.', 'Quebramento exige leitura com art. 341, I: intimação regular e ausência injustificada.'], 'Não ensinar perda automática por qualquer falta, mesmo sem intimação ou com impedimento legítimo.', 'Acusado regularmente intimado comparece à audiência.', 'Hospitalização comprovada exige apreciar motivo justo.', ['Qualquer falta sem análise sempre quebra fiança? Não.', 'Há obrigação de comparecer quando intimado? Sim.'], 'Comparecimento devido','Obrigação condicionada a convocação regular e causas legítimas.')
add(328,'Afiançado precisa de permissão prévia para mudar residência e de comunicação de localização para afastar-se por mais de oito dias.', ['Mudança: permissão prévia.', 'Ausência superior a oito dias: informar onde será encontrado.', 'Obrigações distintas, com controle de descumprimento.'], 'Não confundir comunicar afastamento com pedir permissão para mudar residência; exatamente oito não é mais de oito.', 'Réu solicita permissão antes da mudança.', 'Viagem de dez dias exige informar lugar onde poderá ser encontrado.', ['Mudança exige permissão prévia? Sim.', 'Afastamento de mais de oito dias exige comunicação? Sim.'], 'Controle de localização','Permissão e informação sobre residência e ausência.')
add(329,'Fiança é formalizada em termo e certificada nos autos, com notificação das obrigações e consequências.', ['Livro especial e formalidades descritas; integrar documentação atual aplicável.', 'Assinaturas da autoridade e prestador.', 'Réu e prestador recebem ciência dos arts. 327/328.'], 'Registro não é só recibo de pagamento; ciência das obrigações deve constar.', 'Termo é assinado e certidão juntada com informação das obrigações.', 'Pagamento por terceiro não elimina ciência do acusado e do prestador.', ['Deve notificar obrigações? Sim.', 'Termo dispensa certidão nos autos? Não.'], 'Termo de fiança','Formalização e ciência da garantia.')
add(330,'Fiança admite dinheiro, bens preciosos, títulos públicos e hipoteca inscrita em primeiro lugar, com avaliações pertinentes.', ['Avaliação imediata de imóvel ou preciosos por perito.', 'Títulos públicos pela cotação; nominativos livres de ônus comprovadamente.', 'Garantia definitiva não significa imutabilidade ou impossibilidade de cassação/reforço.'], 'Não aceitar qualquer título privado como se fosse título público enumerado.', 'Bem precioso é avaliado pelo perito designado.', 'Título nominativo com ônus não satisfaz comprovação de liberdade prevista.', ['Pode ser hipoteca de primeiro grau? Sim.', 'Definitiva impede reforço posterior? Não.'], 'Modalidade de caução','Meio patrimonial admitido para garantir obrigações.')
add(331,'Valor segue repartição arrecadadora ou depositário público, com comprovantes; impossibilidade de depósito imediato tem solução e prazo.', ['Entrega excepcional ao escrivão ou pessoa abonada a critério da autoridade.', 'Destino regular dentro de três dias e registro no termo.'], 'Não manter valor indefinidamente fora do depósito regular.', 'Sem depósito pronto, autoridade designa responsável e regulariza em três dias.', 'Entrega excepcional não autoriza gasto ou apropriação privada.', ['Prazo excepcional é três dias? Sim.', 'Deve haver comprovantes nos autos? Sim.'], 'Depósito da garantia','Custódia formal dos valores.')
add(332,'No flagrante, autoridade do auto concede fiança dentro de sua competência; prisão por mandado segue autoridades previstas, com limites atuais.', ['Integrar limite policial do art. 322.', 'Juiz emissor ou autoridade destinatária de requisição nos termos legais.'], 'Artigo não amplia competência policial para pena máxima acima de quatro nem torna crime inafiançável afiançável.', 'Autoridade do flagrante arbitra garantia em delito permitido e faixa de competência.', 'Pena superior ao limite policial exige juiz, ainda que polícia presida auto.', ['Presidir auto elimina limite do art. 322? Não.', 'Há regra própria para mandado? Sim.'], 'Competência integrada','Identificação da autoridade respeitando limites.')
add(333,'Concessão da fiança independe de audiência prévia do MP; após prestação, MP recebe vista para providências pertinentes.', ['Não atrasar concessão exigindo oitiva prévia inexistente.', 'Controle posterior permanece.'], 'Dispensa de audiência prévia não retira fiscalização posterior.', 'Fiança é prestada e processo segue ao MP para manifestação.', 'Não suspender concessão apenas esperando parecer prévio como requisito geral.', ['Parecer prévio é requisito aqui? Não.', 'MP terá vista depois? Sim.'], 'Controle posterior','Manifestação após prestação da garantia.')
add(334,'Fiança pode ser prestada enquanto condenação não transitar em julgado, observada admissibilidade.', ['Limite temporal específico.', 'Não afasta regime de execução imediata do júri ou outros fundamentos cautelares.'], 'Antes do trânsito não significa direito universal a fiança em qualquer delito ou título de prisão.', 'Em caso juridicamente afiançável, garantia é prestada antes do trânsito.', 'Crime inafiançável não passa a admitir garantia por estar em recurso.', ['O marco textual é trânsito da condenação? Sim.', 'O prazo elimina vedações de fiança? Não.'], 'Momento da prestação','Janela legal condicionada à admissibilidade.')
add(335,'Recusa ou demora policial permite petição simples ao juiz por preso ou outra pessoa, com decisão em 48 horas.', ['Via judicial para controle da concessão.', 'Preservar requisitos e vedações de fundo.'], 'Petição não torna fiança cabível onde lei veda.', 'Familiar apresenta pedido ao juiz diante de recusa policial.', 'Juiz decide em prazo previsto após avaliar cabimento.', ['Terceiro pode peticionar pelo preso? Sim.', 'Decisão tem prazo de 48 horas? Sim.'], 'Controle da recusa','Pedido judicial diante de negativa ou atraso.')
add(336,'Fiança atende encargos patrimoniais legais se houver condenação, inclusive hipótese de prescrição depois da sentença nos termos do parágrafo.', ['Custas, indenização, prestação pecuniária e multa.', 'Regra especial alcança prescrição posterior à sentença condenatória.'], 'Fiança não é multa paga antecipadamente em toda hipótese; comparar restituição do art. 337.', 'Condenação permite destinação aos encargos legalmente devidos.', 'Absolvição definitiva segue restituição, não retenção como punição.', ['Pode servir à indenização do dano? Sim.', 'Toda fiança é automaticamente confiscada? Não.'], 'Destinação aos encargos','Aplicação do patrimônio conforme resultado e obrigações.')
add(337,'Sem efeito ou com absolvição/extinção definitiva, restitui-se valor atualizado sem desconto, ressalvada hipótese do art. 336, parágrafo único.', ['Atualização do valor.', 'Exceção específica não pode ser ignorada.'], 'Não ensinar devolução universal sem considerar prescrição posterior à condenação na regra remetida.', 'Absolvição definitiva gera restituição atualizada na hipótese.', 'Prescrição após sentença condenatória demanda integrar exceção do art. 336.', ['Restituição prevista considera atualização? Sim.', 'Há ressalva expressa? Sim.'], 'Restituição da fiança','Devolução conforme resultado e exceção legal.')
add(338,'Reconhecido que fiança não era cabível, ela é cassada em qualquer fase processual.', ['Controle de cabimento originário.', 'Cassação difere de quebra por comportamento posterior.'], 'Cassar garantia não dispensa analisar título legítimo para manter prisão.', 'Descobre-se vedação legal já existente e juiz cassa garantia.', 'Não confundir essa situação com faltar injustificadamente a ato.', ['Cassação por não cabimento é possível em qualquer fase? Sim.', 'É o mesmo que quebramento? Não.'], 'Cassação por incabimento','Retirada da garantia juridicamente inadmissível.')
add(339,'Mudança da classificação para crime inafiançável leva à cassação da fiança.', ['Exige reconhecimento da nova classificação e inafiançabilidade.', 'Comparar reforço quando nova classificação ainda admite garantia.'], 'Não transformar toda reclassificação em cassação automática.', 'Nova classificação é hedionda e não admite fiança.', 'Se continua afiançável mas muda valor exigível, avaliar reforço, não cassação por este fundamento.', ['Toda nova classificação é inafiançável? Não.', 'Inafiançabilidade reconhecida fundamenta cassação? Sim.'], 'Cassação por reclassificação','Garantia incompatível com nova classificação.')
add(340,'Reforço corrige fiança insuficiente por engano, perda de valor dos bens ou classificação nova que o exija.', ['Hipóteses dos três incisos.', 'Falta de reforço exige integração com condição econômica e regras atuais de cautelares.', 'Não converter impossibilidade financeira em prisão automática.'], 'Parágrafo histórico sobre recolhimento deve integrar arts. 282, 312, 321 e 350; pobreza não substitui risco concreto.', 'Bem caucionado perde valor e autoridade aprecia reforço adequado.', 'Réu comprova impossibilidade financeira: analisar dispensa/ajuste e requisitos, sem prender só por falta de dinheiro.', ['Depreciação pode justificar reforço? Sim.', 'Incapacidade econômica basta por si para preventiva? Não.'], 'Reforço da garantia','Recomposição sujeita a legalidade e condição econômica.')
add(341,'Quebra ocorre nas condutas previstas, com intimação regular e justa causa examinada quando cabível.', ['Falta injustificada ao ato; obstrução deliberada.', 'Descumprimento de cautelar cumulada.', 'Resistência injustificada à ordem; nova infração dolosa.'], 'Não equiparar automaticamente acidente culposo à nova infração dolosa do inciso V.', 'Afiançado obstrui deliberadamente produção de prova e juiz aprecia quebra.', 'Ausência médica comprovada não preenche simples falta injustificada.', ['Inciso V exige nova infração dolosa? Sim.', 'Obstrução prevista é deliberada? Sim.'], 'Quebramento','Consequência das violações legalmente definidas.')
add(342,'Reforma da decisão que declarou quebra restaura efeitos da fiança.', ['Depende de reforma do julgamento pertinente.', 'Não confundir simples pedido pendente com reforma efetiva.'], 'Recorrer não equivale por si a obter reforma.', 'Decisão de quebra é reformada e garantia subsiste em seus efeitos.', 'Pedido ainda sem decisão não deve ser apresentado como restauração consumada.', ['Reforma restaura efeitos? Sim.', 'Petição pendente já é reforma? Não.'], 'Subsistência restaurada','Efeito da reversão do julgamento de quebra.')
add(343,'Quebra injustificada perde metade da fiança; juiz analisa outras cautelares ou preventiva cabível.', ['Metade, não totalidade.', 'Prisão exige requisitos, não é consequência obrigatória.', 'Distinguir perda total do art. 344.'], 'Não ensinar toda quebra como perda integral ou prisão automática.', 'Quebra injustificada de garantia de dez unidades perde cinco, com análise das medidas.', 'Se não há requisitos de preventiva, a consequência patrimonial não os cria.', ['Quebra injustificada perde metade? Sim.', 'Impõe sempre preventiva? Não.'], 'Perda parcial','Sanção patrimonial por quebra injustificada.')
add(344,'Perda total ocorre se condenado não se apresenta ao início da pena definitivamente imposta.', ['Condenação e não apresentação na hipótese.', 'Distinguir quebra parcial durante processo.'], 'Não reduzir toda perda total a faltar a audiência nem substituir definitivamente por qualquer sentença recorrível.', 'Condenado não se apresenta ao início do cumprimento definitivo e perde total nos termos legais.', 'Falta a audiência durante instrução tem análise de quebra, não esta hipótese idêntica.', ['O artigo prevê perda total? Sim.', 'Refere-se a pena definitivamente imposta? Sim.'], 'Perdimento total','Consequência da não apresentação ao cumprimento definitivo.')
add(345,'Na perda, deduzem-se custas e encargos e recolhe-se saldo ao fundo penitenciário nos termos legais.', ['Destinação pública do saldo.', 'Deduções dos encargos pertinentes.'], 'Não entregar todo valor ao agente executor ou destinar livremente.', 'Após deduções legais, saldo perdido segue ao fundo penitenciário.', 'Encargos precisam ser apurados, sem desconto fictício.', ['Há dedução de encargos previstos? Sim.', 'Saldo perdido vai livremente ao executor? Não.'], 'Destinação da perda','Aplicação pública após deduções legais.')
add(346,'Em quebramento, valor sujeito ao regime de perda segue deduções e recolhimento ao fundo penitenciário.', ['Integrar metade perdida do art. 343.', 'Remissão às deduções do art. 345.', 'Não transformar quebramento em perda de todo depósito.'], 'Ler destinação junto à extensão da perda parcial, não isoladamente.', 'Metade perdida por quebra sofre deduções legais e destinação prevista.', 'A parte não perdida não é confiscada automaticamente por este artigo.', ['Quebramento equivale sempre a perda total? Não.', 'Há remissão às deduções do art. 345? Sim.'], 'Destino da parcela perdida','Recolhimento conforme extensão legal da sanção.')
add(347,'Fora da hipótese de perda do art. 345, saldo é entregue a quem prestou fiança após encargos devidos.', ['Beneficiário é prestador, que pode ser terceiro.', 'Deduzir obrigações pertinentes.'], 'Não presumir que todo saldo pertence necessariamente ao acusado se outra pessoa prestou.', 'Familiar prestador recebe saldo após encargos legais.', 'Devolução precisa distinguir perda, restituição e destinação dos artigos vizinhos.', ['Pode receber terceiro que prestou? Sim.', 'Deve analisar encargos? Sim.'], 'Saldo devolvido','Restante devido ao prestador nas condições legais.')
add(348,'Garantia hipotecária é executada no juízo cível pelo Ministério Público.', ['Modalidade específica: hipoteca.', 'Não executar como simples apreensão de dinheiro no processo penal.'], 'Competência da execução patrimonial não altera competência para julgar crime.', 'MP promove no cível execução da hipoteca dada em fiança.', 'Não concluir que toda ação penal se torna cível por essa destinação.', ['Execução hipotecária ocorre no cível? Sim.', 'Quem a promove é MP no texto? Sim.'], 'Execução hipotecária','Realização da garantia por via cível.')
add(349,'Bens preciosos dados em fiança podem ser vendidos por determinação do juiz, por leiloeiro ou corretor.', ['Objeto: pedras, objetos ou metais preciosos.', 'Procedimento formal de conversão patrimonial.'], 'Agente não pode vender informalmente por conta própria.', 'Juiz determina venda de bem precioso pelo profissional previsto.', 'Não confundir realização da garantia com apropriação particular.', ['Venda depende de determinação judicial? Sim.', 'Pode executor apropriar-se do bem? Não.'], 'Realização de bens','Conversão formal de garantia preciosa.')
add(350,'Em caso afiançável, situação econômica pode justificar liberdade sem pagamento, com obrigações e cautelares pertinentes.', ['Juiz examina condição financeira.', 'Obrigações dos arts. 327/328 e outras medidas se cabíveis.', 'Descumprimento sem justa causa segue art. 282, §4º.'], 'Dispensa do valor não elimina obrigações nem autoriza preventiva automática por descumprimento.', 'Preso sem recursos recebe liberdade com obrigações legalmente adequadas.', 'Quebra de obrigação exige pedido e análise proporcional do regime cautelar.', ['Dispensa do dinheiro elimina comparecimento? Não.', 'É juiz que examina situação econômica aqui? Sim.'], 'Dispensa econômica','Liberdade sem garantia pecuniária com deveres pertinentes.')
assert len(rows)==30
POV='https://scon.stj.jus.br/SCON/GetInteiroTeorDoAcordao?num_registro=202501926710'
for n in [321,325,340,350]: rows['art-'+str(n)]['remissoes'].append(POV)
rows['art-323']['remissoes'].append('https://portal.stf.jus.br/jurisprudenciaRepercussao/verAndamentoProcesso.asp?classeProcesso=RE&incidente=2690064&numeroProcesso=601384&numeroTema=192')
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'bail articles reviewed')
